  'De afbeelding gaat ongewijzigd naar':
      'Imaginea va fi trimisă nemodificată către',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck nu redactează nimic într-o imagine: chipurile, textul dintr-o captură de ecran și datele vizibile pleacă odată cu ea.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Verificarea imaginilor a găsit aici unul sau mai multe chipuri recognoscibile.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Lângă export sunt create două fișiere cu care destinatarul poate verifica redactările.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'enumeră ce a fost omis, fără valorile propriu-zise. Acest fișier poate însoți raportul.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'conține cheile cu care fiecare valoare redactată poate fi recalculată. Nu trimite acest fișier: astfel redactarea este anulată. Păstrează-l lângă sursă.',
  'slides': 'diapozitive',
  'Achtergehouden': 'Reținut',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Reținut: clasificat mai strict decât prezentarea',
  '1 slide achtergehouden door haar TLP':
      '1 slide reținut din cauza TLP-ului său',
  'slides achtergehouden door hun TLP':
      'slide-uri reținute din cauza TLP-ului lor',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Aceste slide-uri nu sunt incluse la prezentare, la export sau în pachet. Ridicați nivelul TLP al prezentării în Informații prezentare pentru a le include.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Toate slide-urile sunt reținute din cauza clasificării lor TLP — nimic de afișat.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Toate slide-urile sunt reținute din cauza clasificării lor TLP — nimic de exportat.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Toate slide-urile sunt omise sau reținute din cauza clasificării lor TLP — nimic de afișat.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Toate slide-urile sunt omise sau reținute din cauza clasificării lor TLP — nimic de exportat.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Cifrele graficelor nu au fost salvate — există doar în această fereastră:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'În browser nu există recuperare după blocare: dacă închideți această filă, munca nesalvată se pierde. Salvați-vă singur prezentarea.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Baza de date CVE locală (descărcarea o porniți dumneavoastră): OciDeck preia datele în masă prin api.github.com și fișierul de lansare către care indică acea adresă.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Căutare CVE (dezactivată implicit): când este activată, termenul dumneavoastră de căutare ajunge la oglinda CVE configurată și, dacă aceasta nu găsește nimic, la baza de date europeană a ENISA și la MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Un videoclip YouTube sau Vimeo încorporat încarcă playerul de la serviciul respectiv.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  În browser: dacă browserul refuză să preia direct o adresă, OciDeck încearcă din nou prin serverul de la care a venit aplicația; acea adresă ajunge atunci la acel server.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Retragerea nu a fost salvată. La următoarea pornire consimțământul dumneavoastră este din nou valabil.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Un subtitlu de secțiune care anunță o nouă parte a prezentării. Păstrează-l scurt. Adaugă o imagine de fundal din biblioteca de imagini.',
  'Bronnen doorzoeken…': 'Se caută în surse…',
  'Niet doorzocht': 'Necăutat',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Această verificare nu rulează în versiunea web: detectarea fețelor necesită o bibliotecă de sistem pe care browserul nu o are. Folosește versiunea desktop pentru a verifica fețele din imagini.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Tokenul are nevoie de acces de citire și scriere la depozit. Gitea și Forgejo nu au căutare pe server; OciDeck caută local.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Tokenul are nevoie de domeniul repo (sau detaliat: Contents citire și scriere).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Tokenul are nevoie de read_repository, write_repository și read_api. Căutarea pe server necesită Advanced sau Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Căutare rapidă pe server — din cauza întârzierii indexării, un pachet modificat recent poate lipsi.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Conținutul media nu este păstrat într-un fișier .md simplu',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Imaginile, videoclipurile și sunetele alese în această filă există doar în memorie. Un fișier .md simplu nu le păstrează — vor dispărea la redeschidere. Exportă ca pachet .ocideck pentru a lua conținutul media cu tine.',
